        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # We construct a quadrilateral with ∠A=∠C and AB=CD=L.
    # Choose a rational cos(A)=p/q and take L a multiple of q so t=2Lcos(A) is integer.
    # Then choose BD=d with L*sin(A) < d < 0.85L to ensure AD≠BC and nontrivial geometry.
    candidates_q = [6, 8, 9, 10, 12, 14, 15, 16]
    while True:
        q = rng.choice(candidates_q)
        # choose p so that cos in (0.55, 0.95) for a wide feasible range
        p = rng.randint(max(1, int(0.55*q)+1), int(0.95*q)-1)
        cosA = p / q
        if not (0.55 < cosA < 0.95):
            continue
        # choose L as a multiple of q, reasonably large
        mult = rng.randint(12, 40)  # ensures L between ~72 and 640
        L = mult * q
        t = 2 * L * p // q  # integer because L is multiple of q
        # sanity: ensure exact integer computation without rounding
        if 2 * L * p % q != 0:
            continue  # shouldn't happen, but be safe
        # pick d in (L*sinA, 0.85L), integer
        sinA = math.sqrt(max(0.0, 1.0 - cosA * cosA))
        low = int(math.ceil(L * sinA)) + 1  # strictly greater than L*sinA
        high = int(math.floor(0.85 * L))
        if low >= high:
            continue
        d = rng.randint(low, high)
        # perimeter P
        P = 2 * L + t
        # discriminant for AD,BC quadratic must be > 0 (AD != BC)
        # p_prod = L^2 - d^2 must be > 0
        p_prod = L * L - d * d
        if p_prod <= 0:
            continue
        D = t * t - 4 * p_prod
        if D <= 0:
            continue
        # scale factor
        scale = rng.choice([800, 900, 1000, 1100, 1200])
        # To avoid trivial very small or massive value, check the target expression magnitude
        r_value = (t * t) / p_prod - 2.0
        if not (0.5 < r_value < 50.0):
            # keep within reasonable range for contest aesthetics
            continue
        return {
            'equal_side': L,
            'perimeter': P,
            'bd': d,
            'scale': scale
        }

        import math

def verifier(assign):
    # Validate presence
    required = ['equal_side', 'perimeter', 'bd', 'scale']
    for k in required:
        if k not in assign:
            # missing key
            return (False, None)
    L = assign['equal_side']
    P = assign['perimeter']
    d = assign['bd']
    scale = assign['scale']
    # Basic domain checks
    if not (isinstance(L, int) and isinstance(P, int) and isinstance(d, int) and isinstance(scale, int)):
        return (False, None)
    if L <= 0 or d <= 0 or P <= 0 or scale <= 0:
        return (False, None)
    # Derived quantities
    t = P - 2 * L  # t = AD + BC = 2 L cos A when AB = CD = L and ∠A = ∠C
    if t <= 0:
        # invalid (cosA must be positive for convex configuration used)
        return (False, None)
    p_prod = L * L - d * d  # AD * BC
    if p_prod <= 0:
        # invalid product => no real positive AD,BC
        return (False, None)
    # Discriminant for distinct roots (AD != BC)
    D = t * t - 4 * p_prod
    if D <= 0:
        # AD == BC or complex -> violates AD != BC and convexity assumptions
        return (False, None)
    # Compute target expression using Vieta relations:
    # AD and BC are roots of X^2 - t X + p_prod = 0, so
    # AD/BC + BC/AD = (AD^2 + BC^2) / (AD*BC) = (t^2 - 2 p_prod) / p_prod = t^2/p_prod - 2.
    r_value = (t * t) / p_prod - 2.0
    # Final answer
    ans = math.floor(scale * r_value)
    return (True, ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
